package com.fde.ho2.orchestration; import com.fde.ho2.agent.*; import com.fde.ho2.config.*; import com.fde.ho2.model.*; import java.util.*; public class WorkflowOrchestrator { private final WorkflowConfig config; private final Map<AgentType,Agent> agents=new EnumMap<>(AgentType.class); public WorkflowOrchestrator(WorkflowConfig c,List<Agent> a){config=c; for(Agent x:a)agents.put(x.type(),x);} public List<AgentResult> execute(String id){Map<AgentType,AgentResult> done=new EnumMap<>(AgentType.class); List<AgentResult> out=new ArrayList<>(); executeTask(AgentType.PLANNER,id,done,out); executeTask(AgentType.ORDER_ANALYSIS,id,done,out); executeTask(AgentType.RESPONSE,id,done,out); executeTask(AgentType.INVENTORY,id,done,out); return out;} private void executeTask(AgentType t,String id,Map<AgentType,AgentResult>d,List<AgentResult>o){AgentResult r=agents.get(t).execute(id,d);d.put(t,r);o.add(r);System.out.println(t+" -> "+r.output());}}
